from pysat.solvers import Glucose3

n = 35
size = 2 * n

solver = Glucose3()

# Variables: x_{v, i} for v in 1..n, i in 0..size-v-2
# Map (v, i) to an integer ID
def var_id(v, i):
    # v from 1 to n
    # i from 0 to size - v - 2
    # Just use a simple mapping
    return v * size + i + 1

# 1. Each value v has exactly one valid starting position
for v in range(1, n + 1):
    valid_i = [i for i in range(size - v - 1)]
    # At least one
    solver.add_clause([var_id(v, i) for i in valid_i])
    # At most one
    for idx1 in range(len(valid_i)):
        for idx2 in range(idx1 + 1, len(valid_i)):
            solver.add_clause([-var_id(v, valid_i[idx1]), -var_id(v, valid_i[idx2])])

# 2. Each position j is covered exactly once
for j in range(size):
    covering_vars = []
    for v in range(1, n + 1):
        # Can v start at j?
        if j < size - v - 1:
            covering_vars.append(var_id(v, j))
        # Can v end at j?
        if j >= v + 1:
            covering_vars.append(var_id(v, j - v - 1))

    # At least one
    solver.add_clause(covering_vars)
    # At most one
    for idx1 in range(len(covering_vars)):
        for idx2 in range(idx1 + 1, len(covering_vars)):
            solver.add_clause([-covering_vars[idx1], -covering_vars[idx2]])

print("Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    seq = [0] * size
    for v in range(1, n + 1):
        for i in range(size - v - 1):
            if var_id(v, i) in model:
                seq[i] = v
                seq[i + v + 1] = v
    print(seq)
else:
    print("UNSAT")
